// ============================================================================
// ASSEMBLE CONTEXT — PROVIDER-AGNOSTIC SEAM + DETERMINISTIC PACE/FIGURE LOGIC
// ============================================================================
// Input contract: see Sample Race Card header — { race, horses[] }. Reads
// $input only, never a named node reference, so a real provider can replace
// Sample Race Card later without touching this node or the prompt.
//
// Pace scenario, speed-figure ranking, and win-eligible horses are computed
// HERE, deterministically, rather than left to the LLM — same pattern as the
// MLB bullpen-vulnerability three-case rule (favorite/dog reliever counts
// decided in code, handed to the prompt as a fact it must not recalculate).
// ============================================================================

const input = $input.first().json;
const race = input.race || {};
const horses = input.horses || [];

const avg = arr => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null;
const round1 = n => (n === null || n === undefined) ? null : Math.round(n * 10) / 10;

// "8-1" / "5-2" morning-line strings -> decimal price (odds-to-1).
function parseMorningLine(ml) {
  if (!ml) return null;
  const m = String(ml).match(/(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)/);
  if (!m) return null;
  const num = parseFloat(m[1]), den = parseFloat(m[2]);
  return den ? num / den : null;
}

// Collapse the provider's running-style vocabulary to the three buckets this
// logic reasons about. "Pace presser" sits just off the speed, so it's
// grouped with Stalker for win-eligibility purposes, not with Early.
function normalizeStyle(style) {
  const s = (style || '').toLowerCase();
  if (s.includes('early')) return 'Early';
  if (s.includes('closer')) return 'Closer';
  return 'Stalker'; // Pace presser, Stalker, or unrecognized
}

const CLASS_RANK = {
  'claiming': 1, 'allowance n1x': 3, 'allowance n2x': 4, 'allowance n3x': 5,
  'allowance optional claiming (n1x)': 3, 'allowance optional claiming (n2x)': 4,
  'allowance': 3, 'stakes': 6, 'graded stakes': 7
};
const rankOf = (label) => {
  const key = (label || '').toLowerCase().trim();
  for (const [k, v] of Object.entries(CLASS_RANK)) if (key.includes(k)) return v;
  return null;
};

// ---- Per-horse deterministic stats ----
const computed = horses.map(h => {
  const lastStarts = h.lastStarts || [];
  const figs = lastStarts.slice(0, 3).map(s => s.speedFigure).filter(v => typeof v === 'number');
  const avg_fig = round1(avg(figs));
  const best_fig = figs.length ? Math.max(...figs) : null;
  const run_style = normalizeStyle(h.runningStyle);
  const days_off = typeof h.daysSinceLastRace === 'number' ? h.daysSinceLastRace : null;
  const layoff_flag = days_off !== null && days_off >= 90;
  const ml_decimal = parseMorningLine(h.morningLine);
  return { ...h, figs, avg_fig, best_fig, run_style, days_off, layoff_flag, ml_decimal };
});

// ---- pace_scenario: CONTESTED (3+ Early), LONE_SPEED (exactly 1 Early), else NORMAL ----
const earlyHorses = computed.filter(h => h.run_style === 'Early');
let pace_scenario = 'NORMAL';
if (earlyHorses.length >= 3) pace_scenario = 'CONTESTED';
else if (earlyHorses.length === 1) pace_scenario = 'LONE_SPEED';

// ---- figure_rank: all horses with a figure, ranked by avg_fig desc ----
const figure_rank = computed
  .filter(h => h.avg_fig !== null)
  .sort((a, b) => b.avg_fig - a.avg_fig)
  .map(h => ({ name: h.name, avg_fig: h.avg_fig, best_fig: h.best_fig, run_style: h.run_style }));

// ---- speed_edge: top Early horse beats every other Early horse by 3+ avg_fig points ----
let speed_edge = false;
let speed_edge_horse = null;
if (earlyHorses.length >= 2) {
  const earlySorted = earlyHorses.filter(h => h.avg_fig !== null).sort((a, b) => b.avg_fig - a.avg_fig);
  if (earlySorted.length >= 2 && (earlySorted[0].avg_fig - earlySorted[1].avg_fig) >= 3) {
    speed_edge = true;
    speed_edge_horse = earlySorted[0].name;
  }
}

// ---- eligible_win_candidates ----
let eligible_win_candidates = [];
let loneSpeedHorse = null;
const byFigDesc = (a, b) => (b.avg_fig ?? -Infinity) - (a.avg_fig ?? -Infinity);

if (pace_scenario === 'CONTESTED') {
  const nonEarly = computed.filter(h => h.run_style !== 'Early').sort(byFigDesc).map(h => h.name);
  eligible_win_candidates = speed_edge ? [speed_edge_horse, ...nonEarly] : nonEarly;
} else if (pace_scenario === 'LONE_SPEED') {
  loneSpeedHorse = earlyHorses[0]?.name ?? null;
  const rest = computed.filter(h => h.name !== loneSpeedHorse).sort(byFigDesc).map(h => h.name);
  eligible_win_candidates = loneSpeedHorse ? [loneSpeedHorse, ...rest] : rest;
} else {
  eligible_win_candidates = [...computed].sort(byFigDesc).map(h => h.name);
}

// ---- value_candidates: eligible horses at 4-1 (decimal >= 4) or higher ----
const value_candidates = computed
  .filter(h => eligible_win_candidates.includes(h.name) && h.ml_decimal !== null && h.ml_decimal >= 4)
  .map(h => h.name);

// ---- PRE-COMPUTED FACTS text block handed to the prompt ----
const figureRankStr = figure_rank
  .map((h, i) => `${i + 1}. ${h.name} — avg ${h.avg_fig} (best ${h.best_fig}) [${h.run_style}]`)
  .join('\n');

const layoffFlagged = computed.filter(h => h.layoff_flag).map(h => `${h.name} (${h.days_off} days off)`);

const paceScenarioLine = pace_scenario === 'CONTESTED'
  ? `CONTESTED — ${earlyHorses.length} horses project Early (${earlyHorses.map(h => h.name).join(', ')}).` +
    (speed_edge
      ? ` SPEED EDGE: ${speed_edge_horse} clears the other Early horses by 3+ avg-figure points — it is the only Early horse still win-eligible.`
      : ' NO SPEED EDGE among the Early horses — none clears the others by 3+ points, so no Early horse is win-eligible.')
  : pace_scenario === 'LONE_SPEED'
  ? `LONE SPEED — ${loneSpeedHorse} is the only horse projecting Early; upgraded to the top win candidate.`
  : 'NORMAL — no 3+ horse pace jam and no lone leader; pace is not a deciding factor for eligibility.';

const preComputedFactsStr = [
  `PACE SCENARIO: ${paceScenarioLine}`,
  ``,
  `FIGURE RANK (avg of last 3 speed figures, best of last 3, running style):`,
  figureRankStr,
  ``,
  `ELIGIBLE WIN CANDIDATES — your BOBBY'S PICK must be one of these: ${eligible_win_candidates.join(', ')}`,
  `VALUE CANDIDATES (eligible horses at 4-1 or higher): ${value_candidates.length ? value_candidates.join(', ') : 'none'}`,
  `LAYOFF FLAGS (90+ days off — must be named next to the horse if it's your Pick or Value Play): ${layoffFlagged.length ? layoffFlagged.join(', ') : 'none'}`
].join('\n');

// ---- Per-horse snapshot lines (unchanged logic, reusing `computed` stats) ----
const horseLines = computed.map(h => {
  const lastStarts = h.lastStarts || [];
  const figStr = h.figs.length ? h.figs.join(', ') + (h.avg_fig !== null ? ` (avg ${h.avg_fig})` : '') : 'no recent figures';

  const lastClassRank = rankOf(lastStarts[0]?.class);
  const currentRank = rankOf(h.currentClass);
  let classMove = 'class move unclear from data';
  if (lastClassRank !== null && currentRank !== null) {
    if (currentRank > lastClassRank) classMove = 'moving UP in class';
    else if (currentRank < lastClassRank) classMove = 'moving DOWN in class (drop)';
    else classMove = 'same class level';
  }

  const lastSurface = lastStarts[0]?.surface;
  const lastDistance = lastStarts[0]?.distance;
  const surfaceFit = lastSurface && race.surface && lastSurface !== race.surface
    ? `SURFACE SWITCH: last raced on ${lastSurface}, today is ${race.surface} — unproven on today's surface`
    : 'surface matches recent starts';
  const distanceFit = lastDistance && race.distance && lastDistance !== race.distance
    ? `distance change: last at ${lastDistance}, today ${race.distance}`
    : 'distance matches recent starts';

  const layoffNote = h.layoff_flag
    ? `LAYOFF RISK: ${h.days_off} days since last start (90+)`
    : `${h.days_off ?? 'unknown'} days since last start`;

  const extraNote = h.note ? ` NOTE: ${h.note}` : '';

  return [
    `#${h.postPosition} ${h.name} — ML ${h.morningLine} — ${h.runningStyle || 'running style unknown'} (${h.run_style})`,
    `   Jockey: ${h.jockey} (${h.jockeyWinPct}% wins) | Trainer: ${h.trainer} (${h.trainerWinPct}% wins)`,
    `   Last 3 speed figures: ${figStr}`,
    `   Class: ${h.currentClass} — ${classMove}`,
    `   ${surfaceFit}; ${distanceFit}`,
    `   ${layoffNote}${extraNote}`
  ].join('\n');
});

const paceGroups = { Early: [], Stalker: [], Closer: [] };
for (const h of computed) if (paceGroups[h.run_style]) paceGroups[h.run_style].push(h.name);
const paceStr = Object.entries(paceGroups)
  .filter(([, names]) => names.length)
  .map(([style, names]) => `${style}: ${names.join(', ')}`)
  .join(' | ') || 'Pace mix unclear from data';

const raceHeader = `🏇 RACE: ${race.track} — Race ${race.raceNumber} — ${race.distance} — ${race.surface} — ${race.condition}`;

return [{
  json: {
    raceHeader,
    raceMeta: race,
    fieldSnapshotStr: horseLines.join('\n\n'),
    paceStr,
    weatherStr: race.weather || 'Weather not available',
    purseStr: race.purse || 'Purse not available',
    dataSource: race.dataSource || 'UNKNOWN',
    horseCount: horses.length,
    horsesRaw: horses,
    preComputedFactsStr,
    pace_scenario,
    eligible_win_candidates,
    value_candidates
  }
}];
